inline constexpr int CRAFT_CLASS_COUNT = 5;
inline constexpr int CRAFT_MATERIAL_COUNT = 37;
inline constexpr int CRAFT_BLUEPRINT_COUNT = 1606;
inline constexpr int CRAFT_SLOT_COUNT = 4286;
inline constexpr int CRAFT_SOURCE_COUNT = 3403;
inline constexpr int CRAFT_POOL_ITEM_COUNT = 31490;
inline constexpr int CRAFT_OTHER_POOL_COUNT = 1375;
